let img;
let effect;

function draw() {
  clear();

  effect.show();
  effect.update();
}

class Particle {
  constructor(effect, x, y, color_) {
    this.effect = effect;
    this.x = random() * this.effect.width_;
    this.y = random() * this.effect.height_;
    this.originX = floor(x);
    this.originY = floor(y);
    this.color_ = color_;
    this.size = this.effect.gap;
    this.vx = 0; //random() * 2 - 1;
    this.vy = 0; //random() * 2 - 1;
    this.ease = 0.05;
    this.dx = 0;
    this.dy = 0;
    this.friction = 0.8;
    this.force = 0;
    this.angle= 0;
  }

  show() {
    fill(this.color_);
    noStroke();
    rect(this.x, this.y, this.size, this.size);
  }

  update() {
    
    this.dx = this.effect.mouse.x - this.x; 
    this.dy = this.effect.mouse.y - this.y;
    this.distance = this.dx * this.dx + this.dy * this.dy;
    
    this.force = -this.effect.mouse.radius / this.distance;
    
    if(this.distance < this.effect.mouse.radius){
      this.angle = atan2(this.dy, this.dx);
      this.vx += this.force * cos(this.angle);
      this.vy += this.force * sin(this.angle)
    }
    
    this.x += (this.vx *= this.friction) + (this.originX - this.x) * this.ease;
    this.y += (this.vy *= this.friction) + (this.originY - this.y) * this.ease;
  }
}

class Effect {
  constructor(width_, height_) {
    this.width_ = width_;
    this.height_ = height_;
    this.particlesArray = [];
    this.image_ = img;
    this.centerX = this.width_ * 0.5;
    this.centerY = this.height_ * 0.5;
    this.x = this.centerX - this.image_.width * 0.5;
    this.y = this.centerY - this.image_.height * 0.5;
    this.gap = 2;
    this.mouse = {
      radius: 5000,
      x: undefined,
      y: undefined
    }
    
  }

  init() {
    this.image_.loadPixels();
    //image(this.image_, this.x, this.y);

    loadPixels();

    for (let y = 0; y < this.image_.height; y += this.gap) {
      for (let x = 0; x < this.image_.width; x += this.gap) {
        // Convert to index
        const index = 4 * (y * this.image_.width + x);

        const r = this.image_.pixels[index + 0];
        const g = this.image_.pixels[index + 1];
        const b = this.image_.pixels[index + 2];
        const a = this.image_.pixels[index + 3];

        if (a > 0) {
          const color_ = color(r, g, b);
          // ⭐ offset pixel positions to center the image
          const px = x + this.x;
          const py = y + this.y;
          this.particlesArray.push(new Particle(this, px, py, color_));
        }
      }
    }
  }

  show() {
    this.particlesArray.forEach((particle) => particle.show());
  }

  update() {
    this.particlesArray.forEach((particle) => particle.update());
    this.mouse.x = mouseX;
    this.mouse.y = mouseY;
    //console.log(this.mouse.x)
  }
}

